import {fields,normalize,digits,contacts,searchRecords,todayParts,upcomingBirthdays,autoMap,rowsToRecords,parseCSV,birthdayInfo} from './data.js';
import * as dataEngine from './data.js';
import {renderBirthdayCard,makeCaption} from './card.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fa=v=>new Intl.NumberFormat('fa-IR',{useGrouping:false}).format(v), safeImage=v=>typeof v==='string'&&/^data:image\/(png|jpeg|webp|gif|svg\+xml);/i.test(v)&&v.length<6000000;
const schoolDefault='دبیرستان شهید هاشمی‌نژاد ۴';
let state,db,selected=null,type='all',query='',job='',className='',page=0,bdayDays=0,toastTimer,writeQueue=Promise.resolve(),importState={},cardToken=0;
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.7}})}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('hamneshan-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('desk');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readState(){return new Promise((resolve,reject)=>{const r=db.transaction('desk').objectStore('desk').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function persist(){const snapshot=structuredClone(state);$('#saveState').textContent='در حال ذخیره…';writeQueue=writeQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(new Error('storage'));const tx=db.transaction('desk','readwrite');tx.objectStore('desk').put(snapshot,'state');tx.oncomplete=()=>{ $('#saveState').textContent='ذخیره‌شده در این دستگاه';resolve()};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}));writeQueue.catch(()=>{$('#saveState').textContent='ذخیره نشد؛ پشتیبان بگیرید';toast('ذخیره‌سازی انجام نشد. برای حفظ اطلاعات، نسخهٔ پشتیبان بگیرید.');});return writeQueue}
function createDemo(){const t=todayParts(),m=t.month,d=t.day;const base={birthdayCalendar:'jalali',extras:{},photo:null};const people=[['آرین فرهمند','student','دهم','۱۰۱','مهندس عمران','پزشک','09151114821','09152225678',`${1390}/${m}/${d}`],['پارسا نیک‌روش','student','یازدهم','۱۱۰۲','پزشک','دبیر','09153334821','09154446789',`${1389}/${m}/${d}`],['سینا مهرآیین','student','دوازدهم','۱۲۰۱','کارمند','حسابدار','09155558123','09156667890','1388/09/16'],['کیان رادمنش','student','دهم','۱۰۲','دندان‌پزشک','مهندس','09157779345','09158888901','1390/11/08'],['آرمان دانش‌نیا','student','یازدهم','۱۱۰۱','فروشنده','پرستار','09159990456','09150009012','1389/04/21'],['مانی شکیبا','student','دهم','۱۰۱','مهندس برق','کارشناس آزمایشگاه','09151111567','09152220123','1390/02/14'],['بردیا سپهری','student','دوازدهم','۱۲۰۲','وکیل','کارمند','09153332678','09154441234','1388/12/29'],['سامان امیدی','student','یازدهم','۱۱۰۲','پزشک','پزشک','09155553789','09156662345','1389/07/12'],['مهدی مهرپرور','teacher','','','ریاضی','','09157774821','','1362/01/16'],['رضا فروزان','teacher','','','فیزیک','','09158885901','','1365/09/21'],['علی نیک‌اندیش','teacher','','','زبان انگلیسی','','09159996012','','1358/03/11']];return {format:'hamneshan-backup',version:1,demo:true,records:people.map((p,i)=>({...base,id:'demo-'+i,name:p[0],type:p[1],grade:p[2],className:p[3],fatherJob:p[1]==='student'?p[4]:'',motherJob:p[5],subject:p[1]==='teacher'?p[4]:'',fatherName:p[1]==='student'?'ولی '+p[0]:'',phone:p[1]==='teacher'?p[6]:'',fatherPhone:p[1]==='student'?p[6]:'',motherPhone:p[7],homePhone:p[1]==='student'?'05133334821':'',birthday:p[8]})),settings:{schoolName:schoolDefault,logo:null}}}
function validateBackup(v){if(v?.format!=='hamneshan-backup'||v.version!==1||!Array.isArray(v.records)||v.records.length>30000)throw new Error('فایل پشتیبان معتبر هم‌نشان نیست.');const ids=new Set();const records=v.records.map((r,i)=>{if(!r||typeof r.name!=='string'||!r.name.trim()||!['student','teacher'].includes(r.type))throw new Error('مشخصات فرد در ردیف '+fa(i+1)+' معتبر نیست.');let id=typeof r.id==='string'?r.id:'restore-'+i;if(ids.has(id))throw new Error('شناسهٔ تکراری در پشتیبان وجود دارد.');ids.add(id);const out={...r,id,photo:safeImage(r.photo)?r.photo:null};for(const f of fields)if(out[f.key]!=null)out[f.key]=String(out[f.key]).slice(0,20000);out.extras=Object.fromEntries(Object.entries(r.extras||{}).slice(0,200).map(([k,val])=>[String(k).slice(0,500),String(val??'').slice(0,20000)]));return out});return {format:'hamneshan-backup',version:1,records,demo:!!v.demo,report:v.report||null,settings:{schoolName:String(v.settings?.schoolName||schoolDefault).slice(0,150),logo:safeImage(v.settings?.logo)?v.settings.logo:null}}}
function avatar(r,cls='person-avatar'){return `<span class="${cls} ${['','purple','blue','rose','green'][state.records.indexOf(r)%5]||''}">${safeImage(r.photo)?`<img src="${esc(r.photo)}" alt="">`:esc(r.name.trim().split(/\s+/).map(v=>v[0]).slice(0,2).join('‌'))}</span>`}
const birthdayRecords=()=>state.records.filter(r=>!r.duplicateOf);
function updateHeader(){const t=todayParts();$('#todayDate').innerHTML='<i data-lucide="calendar-days"></i>'+esc(t.label);$('#schoolName').textContent=state.settings.schoolName;$('#schoolLogo').innerHTML=`<img src="${state.settings.logo?esc(state.settings.logo):'./assets/school-logo.svg'}" alt="لوگوی مدرسه">`;$('#demoBanner').hidden=!state.demo;$('#navStudents').textContent=fa(state.records.filter(x=>x.type==='student').length);$('#navTeachers').textContent=fa(state.records.filter(x=>x.type==='teacher').length);$('#navBirthdays').textContent=fa(upcomingBirthdays(birthdayRecords(),new Date(),0).length)}
function renderStats(){const students=state.records.filter(r=>r.type==='student').length,teachers=state.records.length-students,today=upcomingBirthdays(birthdayRecords(),new Date(),0).length,phoneCount=state.records.reduce((n,r)=>n+contacts(r).length,0);$('#stats').innerHTML=[[students,'دانش‌آموز','graduation-cap','student'],[teachers,'پروندهٔ دبیر','notebook-pen','teacher'],[today,'تولد امروز','cake','birthdays'],[phoneCount,'شمارهٔ تماس','contact-round','all']].map(([n,label,icon,nav])=>`<button class="stat-card" data-stat="${nav}"><span class="stat-icon"><i data-lucide="${icon}"></i></span><span><div class="stat-value">${fa(n)}</div><div class="stat-label">${label}</div></span><i class="stat-arrow" data-lucide="arrow-up-left"></i></button>`).join('')}
function renderClassOptions(){const current=$('#classFilter').value;$('#classFilter').innerHTML='<option value="">همهٔ کلاس‌ها</option>'+[...new Set(state.records.map(r=>r.className).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fa')).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('#classFilter').value=current}
function results(){const q=digits(query).replace(/\D/g,'');const callMode=/^[\d۰-۹٠-٩\s+()\-]+$/.test(query)&&q.length===4;return searchRecords(state.records,query,{type,job}).filter(x=>(!callMode||x.matches.some(m=>m.kind==='phone'))&&(!className||x.record.className===className))}
function renderResults(){const list=results();page=Math.min(page,Math.max(0,Math.ceil(list.length/5)-1));$('#resultsTitle').textContent=query?'نتیجه‌های جست‌وجو':'آدم‌های مدرسه';$('#resultCount').textContent=fa(list.length)+' پرونده';$('#listFooter').textContent=list.length?`نمایش ${fa(page*5+1)} تا ${fa(Math.min((page+1)*5,list.length))} از ${fa(list.length)} پرونده`:'اطلاعاتی برای نمایش نیست';$('#pageNumber').textContent=fa(page+1);$('#prevPage').disabled=page===0;$('#nextPage').disabled=(page+1)*5>=list.length;$('#clearSearch').hidden=!query;$('#filterDot').hidden=!(job||className);const num=digits(query).replace(/\D/g,'');const numeric=/^[\d۰-۹٠-٩\s+()\-]+$/.test(query)&&num.length>=4;$('#searchNotice').hidden=!numeric;$('#searchNotice').textContent=list.length>1?'چند تطبیق پیدا شد؛ چهار رقم آخر به‌تنهایی هویت تماس‌گیرنده را قطعی نمی‌کند.':'نتیجه بر اساس شمارهٔ ثبت‌شده است؛ برای تلفن مشترک، نسبت تماس‌گیرنده قطعی نیست.';$('#results').innerHTML=list.slice(page*5,(page+1)*5).map(({record:r,matches})=>{const phoneMatches=matches.filter(x=>x.kind==='phone');const c=phoneMatches.length?phoneMatches.map(m=>`<div><span class="phone-number">${esc(m.value)}</span><span class="relationship">${esc(m.role||m.label)}</span></div>`).join(''):query&&matches.length?matches.slice(0,2).map(m=>`<div><strong>${esc(m.label)}:</strong> ${esc(String(m.value).slice(0,45))}</div>`).join(''):contacts(r).length?`<span class="phone-number">${esc(contacts(r)[0].number)}</span><span class="relationship">${esc(contacts(r)[0].role)}</span>`:'شماره‌ای ثبت نشده';return `<button class="person-row ${selected===r.id?'selected':''}" data-person="${esc(r.id)}"><span class="person-main">${avatar(r)}<span style="min-width:0"><div class="person-name">${esc(r.name)}</div><div class="person-sub">${esc(r.type==='teacher'?'دبیر '+(r.subject||'مدرسه'):[r.grade,r.className?'کلاس '+r.className:r.studyField].filter(Boolean).join(' · ')||'دانش‌آموز')}</div></span></span><span class="person-match">${c}</span><i data-lucide="chevron-left"></i></button>`}).join('')||'<div class="empty-state"><i data-lucide="search-x"></i><b>هنوز نشانه‌ای پیدا نکردیم.</b><p>شماره یا عبارت دیگری بنویسید، یا فیلترها را پاک کنید.</p><button class="text-button" data-action="reset">پاک‌کردن جست‌وجو</button></div>';$$('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===type));icons()}
function profileHtml(r){const fieldsShown=[['birthday','تاریخ تولد'],['nationalId','کد ملی'],['fatherName','نام پدر'],['motherName','نام مادر'],['fatherJob','شغل پدر'],['motherJob','شغل مادر'],['subject','تخصص / درس'],['studyField','رشته تحصیلی']].filter(([k])=>r[k]);const raw=Object.entries(r.extras||{}).filter(([k,v])=>v!==''&&v!=null);const more=[...fields.filter(f=>!['name','firstName','lastName','phone','fatherPhone','motherPhone','homePhone',...fieldsShown.map(x=>x[0])].includes(f.key)&&r[f.key]).map(f=>[f.label,r[f.key]]),...raw];const match=searchRecords([r],query,{type:'all',job:''})[0]?.matches.filter(m=>m.kind==='phone').map(m=>m.value)||[];return `<div class="profile-top"><div class="small-label"><span>پروندهٔ ${r.type==='teacher'?'دبیر':'دانش‌آموز'}</span><span>${r.duplicateOf?'ثبت تکراری؛ نیازمند بررسی':'اطلاعات در یک نگاه'}</span></div>${avatar(r,'profile-avatar')}<h2 class="profile-name">${esc(r.name)}</h2><div class="profile-meta"><span>${r.type==='teacher'?'دبیر':esc(r.grade||'دانش‌آموز')}</span>${r.className?`<span>کلاس ${esc(r.className)}</span>`:''}</div></div><div class="profile-body"><h3 class="profile-section-title"><i data-lucide="phone"></i>راه‌های تماس</h3>${contacts(r).map(c=>`<div class="contact-row ${match.includes(c.number)?'is-match':''}"><span class="contact-label">${esc(c.role)}</span><span class="contact-number">${esc(c.number)}</span><button class="copy-phone" data-copy="${esc(c.number)}" title="کپی شماره"><i data-lucide="copy"></i></button></div>`).join('')||'<p class="muted" style="font-size:12px">شماره‌ای ثبت نشده است.</p>'}<dl class="details-grid">${fieldsShown.map(([k,l])=>`<div><dt>${l}</dt><dd>${esc(r[k])}</dd></div>`).join('')}</dl><div class="profile-actions"><button class="button soft" data-card="${esc(r.id)}"><i data-lucide="gift"></i>کارت تبریک</button><button class="button" data-edit="${esc(r.id)}"><i data-lucide="square-pen"></i>ویرایش و عکس</button></div>${more.length?`<details class="profile-more"><summary>نمایش تمام مشخصات (${fa(more.length)} مورد)</summary><dl>${more.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`:''}</div>`}
function renderProfile(){const r=state.records.find(r=>r.id===selected);$('#profile').innerHTML=r?profileHtml(r):'<div class="profile-empty"><i data-lucide="contact-round"></i><h2>یک نفر را انتخاب کنید</h2><p>مشخصات کامل و تماس‌های خانواده<br>همین‌جا نمایش داده می‌شود.</p></div>';icons()}
function selectPerson(id){selected=id;renderResults();renderProfile();if(matchMedia('(max-width:1050px)').matches){dialog('مشخصات فرد',`<div class="modal-profile">${profileHtml(state.records.find(x=>x.id===id))}</div>`)} }
function renderBirthdays(){const list=upcomingBirthdays(birthdayRecords(),new Date(),bdayDays);$('#birthdayList').innerHTML=list.map(({record:r,daysUntil,dateLabel,leapAdjusted})=>`<div class="birthday-person"><span class="bday-label">${daysUntil===0?'امروز':daysUntil===1?'فردا':fa(daysUntil)+' روز دیگر'}</span>${avatar(r)}<h3>${esc(r.name)}</h3><p>${r.type==='teacher'?'دبیر':esc(r.grade||'دانش‌آموز')} · ${esc(dateLabel)}${leapAdjusted?' *':''}</p><button data-card="${esc(r.id)}">ساخت کارت تبریک <i data-lucide="arrow-up-left"></i></button></div>`).join('')||`<div class="birthday-empty"><i data-lucide="party-popper"></i><b>${bdayDays===0?'امروز تولدی ثبت نشده است.':'در این بازه تولدی ثبت نشده است.'}</b><span style="font-size:11px">${bdayDays===0?'تولدهای هفته و ماه آینده را هم ببینید.':'تاریخ تولد افراد را از پروندهٔ آن‌ها تکمیل کنید.'}</span></div>`;$$('[data-days]').forEach(b=>b.classList.toggle('active',Number(b.dataset.days)===bdayDays));icons()}
function renderAll(){updateHeader();renderStats();renderClassOptions();renderResults();renderProfile();renderBirthdays();icons()}
function dialog(title,html){cardToken++;$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;if(!$('#mainDialog').open)$('#mainDialog').showModal();icons()}
function closeDialog(){$('#mainDialog').close();cardToken++}
function changeNav(nav){if(nav==='birthdays'){$('#birthdaySection').scrollIntoView({behavior:'smooth',block:'center'});bdayDays=30;renderBirthdays()}else if(nav==='jobs'){$('#filters').hidden=false;$('#jobFilter').focus()}else{type=nav;page=0;renderResults();$('#searchInput').focus()}$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));$('#sectionName').textContent={all:'جست‌وجوی سریع',student:'دانش‌آموزان',teacher:'دبیران',birthdays:'تقویم تولدها',jobs:'جست‌وجوی شغلی'}[nav]}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('کپی شد.')}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove();toast('کپی شد.')}}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function backup(){download(new Blob([JSON.stringify({...state,createdAt:new Date().toISOString()},null,2)],{type:'application/json'}),'school-data.hamneshan.json');toast('فایل پشتیبان برای ذخیره آماده شد.');}
async function readBackup(file){if(file.size>25*1024*1024)throw new Error('حجم فایل بیشتر از ۲۵ مگابایت است.');return validateBackup(JSON.parse(await file.text()))}
function confirmRestore(v){dialog('بازیابی اطلاعات مدرسه',`<p class="dialog-note">${fa(v.records.length)} پرونده در این پشتیبان وجود دارد. با بازیابی، اطلاعات و عکس‌های فعلی این برنامه جایگزین می‌شوند. پیش از ادامه می‌توانید از اطلاعات فعلی پشتیبان بگیرید.</p><div class="dialog-actions"><button class="button" id="beforeRestoreBackup">دریافت پشتیبان فعلی</button><button class="button" id="cancelRestore">انصراف</button><button class="button primary" id="confirmRestore">جایگزینی و بازیابی</button></div>`);$('#beforeRestoreBackup').onclick=backup;$('#cancelRestore').onclick=closeDialog;$('#confirmRestore').onclick=async()=>{state=v;selected=state.records[0]?.id;query='';$('#searchInput').value='';job='';className='';page=0;try{await persist();closeDialog();renderAll();toast('اطلاعات مدرسه بازیابی شد.')}catch{}}}
async function imageData(file,max=800){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('عکس را با فرمت JPG، PNG یا WebP انتخاب کنید.');if(file.size>10*1024*1024)throw new Error('عکس باید کوچک‌تر از ۱۰ مگابایت باشد.');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*ratio));c.height=Math.max(1,Math.round(bitmap.height*ratio));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/jpeg',.88)}
function settingsDialog(){dialog('تنظیمات و پشتیبان',`<section class="setting-section"><h3>هویت مدرسه</h3><label class="form-label">نام مدرسه<input class="form-input" id="settingSchoolName" value="${esc(state.settings.schoolName)}"></label><div class="asset-preview"><img id="settingLogoPreview" src="${state.settings.logo?esc(state.settings.logo):'./assets/school-logo.svg'}" alt="لوگوی مدرسه"><label class="button file-button"><i data-lucide="image-plus"></i>تغییر لوگو<input id="logoInput" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><button class="text-button" id="restoreLogo">لوگوی اصلی مدرسه</button></div><p>فونت تیترها: B Titr · فونت متن‌ها: B Koodak. هر دو فونت داخل نرم‌افزار قرار دارند.</p><div class="dialog-actions"><button class="button primary" id="saveSettings">ذخیرهٔ تنظیمات</button></div></section><section class="setting-section"><h3>نسخهٔ پشتیبان و انتقال اطلاعات</h3><p>پرونده‌ها و عکس‌ها در همین دستگاه ذخیره می‌شوند. برای جابه‌جایی بین دستگاه‌ها یا نگهداری یک نسخهٔ مستقل، فایل پشتیبان دریافت کنید.</p><div class="dialog-actions"><button class="button" id="backupButton"><i data-lucide="download"></i>دریافت پشتیبان</button><label class="button file-button"><i data-lucide="folder-open"></i>بازیابی پشتیبان<input type="file" id="restoreInput" accept=".json,.hamneshan"></label></div></section><section class="setting-section"><h3>راهنمای تولدها</h3><p>تولدها هر روز با تاریخ تهران به‌روز می‌شوند و هنگام باز بودن نرم‌افزار نمایش داده می‌شوند. در سال‌های غیرکبیسه، تولد ۳۰ اسفند در ۲۹ اسفند نشان داده می‌شود. برای پیام کانال، تصویر و متن تبریک را از کارت تولد دریافت کنید.</p></section><section class="setting-section"><h3>داده‌های نمونه</h3><p>${state.demo?'در حال نمایش نمونه هستید؛ با ورود اولین فایل، نمونه‌ها کنار گذاشته می‌شوند.':'اطلاعات واقعی مدرسه فعال است.'}</p><button class="button" id="showDemo">باز کردن نمونه در صورت خالی بودن اطلاعات</button><button class="button danger" id="clearDatabase">پاک‌کردن اطلاعات این دستگاه</button></section>`);let pendingLogo=state.settings.logo;$('#logoInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.type==='image/svg+xml'){if(f.size>1000000)throw new Error('حجم لوگو زیاد است.');const txt=await f.text();const xml=new DOMParser().parseFromString(txt,'image/svg+xml');if(xml.querySelector('script,foreignObject,parsererror')||[...xml.querySelectorAll('*')].some(n=>[...n.attributes].some(a=>/^on/i.test(a.name)||(/href$/i.test(a.name)&&!a.value.startsWith('#')))))throw new Error('این فایل SVG قابل استفاده نیست.');pendingLogo='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(txt)))}else pendingLogo=await imageData(f);$('#settingLogoPreview').src=pendingLogo;}catch(e){toast(e.message)}};$('#restoreLogo').onclick=()=>{pendingLogo=null;$('#settingLogoPreview').src='./assets/school-logo.svg'};$('#saveSettings').onclick=async()=>{state.settings={schoolName:$('#settingSchoolName').value.trim()||schoolDefault,logo:pendingLogo};try{await persist();closeDialog();renderAll();toast('تنظیمات ذخیره شد.')}catch{}};$('#backupButton').onclick=backup;$('#restoreInput').onchange=async e=>{if(!e.target.files[0])return;try{confirmRestore(await readBackup(e.target.files[0]))}catch(err){toast('فایل قابل بازیابی نیست: '+err.message)}};$('#showDemo').onclick=()=>{if(state.records.length&&!state.demo){toast('برای حفظ اطلاعات واقعی، نمونه‌ها بارگذاری نشدند.');return}state=createDemo();persist();selected=state.records[0].id;closeDialog();renderAll()};$('#clearDatabase').onclick=()=>{dialog('پاک‌کردن اطلاعات این دستگاه',`<p class="dialog-note">${fa(state.records.length)} پرونده و عکس‌های آن‌ها از این برنامه حذف می‌شوند. ابتدا پشتیبان بگیرید. این کار فایل اکسل اصلی را تغییر نمی‌دهد.</p><div class="dialog-actions"><button class="button" id="clearBackup">دریافت پشتیبان</button><button class="button" id="cancelClear">انصراف</button><button class="button danger" id="doClear">حذف همهٔ پرونده‌ها</button></div>`);$('#clearBackup').onclick=backup;$('#cancelClear').onclick=closeDialog;$('#doClear').onclick=async()=>{state.records=[];state.demo=false;selected=null;await persist();closeDialog();renderAll();toast('فهرست اطلاعات پاک شد.')}}}
function editDialog(id){const r=state.records.find(x=>x.id===id);let photo=r.photo;const editable=fields.filter(f=>!['firstName','lastName'].includes(f.key));dialog('ویرایش مشخصات و عکس',`<div class="dialog-note">${esc(r.name)} · ${r.type==='teacher'?'دبیر':'دانش‌آموز'}</div><form id="editForm"><div class="form-grid">${editable.map(f=>`<label>${esc(f.label)}<input name="${esc(f.key)}" value="${esc(r[f.key])}" ${f.key==='name'?'required':''}></label>`).join('')}<label>تقویم تاریخ تولد<select name="birthdayCalendar"><option value="jalali" ${r.birthdayCalendar!=='gregorian'?'selected':''}>شمسی؛ ۱۳۸۹/۰۷/۱۲</option><option value="gregorian" ${r.birthdayCalendar==='gregorian'?'selected':''}>میلادی؛ ۲۰۱۰/۱۰/۰۴</option></select></label><div><span class="form-label">عکس فرد</span><div class="asset-preview"><img id="editPhotoPreview" ${safeImage(photo)?`src="${esc(photo)}"`:'hidden'} alt="عکس فرد"><label class="button file-button">انتخاب عکس<input id="editPhoto" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="text-button" type="button" id="removePhoto">حذف عکس</button></div></div></div><p class="photo-upload-note">اطلاعات دیگرِ فایل اصلی در «تمام مشخصات» محفوظ است. عکس در همین دستگاه ذخیره می‌شود.</p><div class="dialog-actions"><button type="button" class="button" id="cancelEdit">انصراف</button><button class="button primary" type="submit">ذخیرهٔ تغییرات</button></div></form>`);$('#cancelEdit').onclick=closeDialog;$('#editPhoto').onchange=async e=>{try{if(!e.target.files[0])return;photo=await imageData(e.target.files[0]);$('#editPhotoPreview').src=photo;$('#editPhotoPreview').hidden=false}catch(err){toast(err.message)}};$('#removePhoto').onclick=()=>{photo=null;$('#editPhotoPreview').hidden=true};$('#editForm').onsubmit=async e=>{e.preventDefault();const vals=Object.fromEntries(new FormData(e.target));if(vals.birthday&&!birthdayInfo(vals.birthday,vals.birthdayCalendar).valid){toast('تاریخ تولد معتبر نیست؛ تاریخ و نوع تقویم را بررسی کنید.');return}Object.assign(r,vals,{photo});await persist();closeDialog();renderAll();toast('پرونده ذخیره شد.')}}
async function logoData(){if(state.settings.logo)return state.settings.logo;const blob=await (await fetch('./assets/school-logo.svg')).blob();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function cardDialog(id){const r=state.records.find(x=>x.id===id);if(!r)return;const caption=makeCaption(r,state.settings.schoolName);dialog('کارت تبریک تولد',`<div class="birthday-editor"><canvas id="birthdayCanvas" aria-label="پیش‌نمایش کارت تولد"></canvas><div><h3 style="margin-bottom:15px">${esc(r.name)}، تولدت مبارک!</h3><label class="form-label">متن روی کارت و پیام کانال<textarea id="birthdayCaption" class="form-input" maxlength="600">${esc(caption)}</textarea></label><div class="card-options"><label>رنگ کارت <select id="cardTheme"><option value="mint">سبز نعنایی</option><option value="lavender">یاسی</option><option value="peach">هلویی</option></select></label><label class="button file-button">${r.photo?'تغییر عکس':'افزودن عکس'}<input id="birthdayPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label></div><p class="card-help">${r.photo?'عکس ثبت‌شده در کارت استفاده می‌شود.':'هنوز عکسی ثبت نشده است؛ تا افزودن عکس، حروف اول نام نمایش داده می‌شود.'} تصویر مربعی ۱۰۸۰ × ۱۰۸۰ مناسب انتشار در کانال است.</p><div id="cardStatus" class="dialog-status" role="status"></div><div class="dialog-actions"><button class="button" id="copyCaption"><i data-lucide="copy"></i>کپی پیام</button><button class="button purple" id="downloadCard"><i data-lucide="download"></i>دریافت تصویر</button></div></div></div>`);let timeout,ready=false;const localToken=cardToken;const draw=async()=>{ready=false;$('#downloadCard').disabled=true;const token=++cardToken;try{const res=await renderBirthdayCard($('#birthdayCanvas'),r,{schoolName:state.settings.schoolName,logo:await logoData(),caption:$('#birthdayCaption').value,theme:$('#cardTheme').value});if(token!==cardToken)return;$('#cardStatus').textContent=res.warnings?.join(' ')||'کارت آمادهٔ دریافت است.';ready=true;$('#downloadCard').disabled=false}catch(err){if($('#cardStatus'))$('#cardStatus').textContent=err.message||'کارت آماده نشد.'}};$('#birthdayCaption').oninput=()=>{ready=false;clearTimeout(timeout);timeout=setTimeout(draw,300)};$('#cardTheme').onchange=draw;$('#birthdayPhoto').onchange=async e=>{if(!e.target.files[0])return;try{r.photo=await imageData(e.target.files[0]);await persist();renderProfile();draw()}catch(err){toast(err.message)}};$('#copyCaption').onclick=()=>copy($('#birthdayCaption').value);$('#downloadCard').onclick=()=>{if(!ready)return;$('#birthdayCanvas').toBlob(blob=>{if(blob)download(blob,'تولد-'+r.name+'.png')},'image/png')};await draw()}
function importDialog(){importState={type:'student',workbook:null,rows:null,fileName:'',headerRow:1};dialog('ورود اطلاعات مدرسه',`<p class="dialog-note">فایل دانش‌آموزان و دبیران را جداگانه وارد کنید. قالب اصلی فایل‌های مدرسه تشخیص داده می‌شود؛ برای فایل‌های دیگر، ستون‌ها را انتخاب می‌کنید.</p><div class="import-type"><label><input type="radio" name="importType" value="student" checked>فایل دانش‌آموزان</label><label><input type="radio" name="importType" value="teacher">فایل دبیران</label></div><label class="upload-box"><i data-lucide="files"></i><b>فایل را اینجا رها کنید یا انتخاب کنید</b><small>اکسل XLSX و XLS یا CSV با متن UTF-8 · حداکثر ۲۰ مگابایت</small><input id="importFile" type="file" accept=".xlsx,.xls,.csv,.tsv"></label><div class="dialog-actions"><label class="button file-button"><i data-lucide="archive-restore"></i>ورود فایل آمادهٔ مدرسه / پشتیبان<input id="quickRestore" type="file" accept=".json"></label></div><div id="importArea"></div>`);$$('[name=importType]').forEach(b=>b.onchange=()=>{importState.type=b.value;if(importState.rows)showImportMapping()});$('#importFile').onchange=e=>loadImportFile(e.target.files[0]);const box=$('.upload-box');box.ondragover=e=>{e.preventDefault();box.style.background='#e8f3de'};box.ondragleave=()=>box.style.background='';box.ondrop=e=>{e.preventDefault();box.style.background='';loadImportFile(e.dataTransfer.files[0])};$('#quickRestore').onchange=async e=>{try{if(e.target.files[0])confirmRestore(await readBackup(e.target.files[0]))}catch(err){toast(err.message)}}}
async function loadImportFile(file){if(!file)return;try{if(file.size>20*1024*1024)throw new Error('حجم فایل بیشتر از ۲۰ مگابایت است.');importState.fileName=file.name;importState.headerRow=1;if(/\.(csv|tsv)$/i.test(file.name)){importState.workbook=null;importState.rawRows=parseCSV(await file.text());importState.sheetName='';}else{if(!window.XLSX)throw new Error('خواندن اکسل در دسترس نیست.');importState.workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});importState.sheetName=importState.workbook.SheetNames[0];importState.rawRows=XLSX.utils.sheet_to_json(importState.workbook.Sheets[importState.sheetName],{header:1,defval:'',raw:false,blankrows:true})}importState.rows=importState.rawRows;showImportMapping()}catch(e){toast('فایل خوانده نشد: '+e.message)}}
function showImportMapping(){const i=importState;const known=dataEngine.importSchoolRows?.(i.rawRows,i.type);i.known=known;const rowStart=Math.max(0,(i.headerRow||1)-1);i.rows=i.rawRows.slice(rowStart);const headers=i.rows[0]||[];if(!headers.length){$('#importArea').innerHTML='<p class="error-box">فایل خالی است یا سطر عنوان پیدا نشد.</p>';return}const mapping=autoMap(headers);$('#importArea').innerHTML=`<div class="success-box">${esc(i.fileName)} · ${fa(i.rawRows.length-1)} سطر پس از عنوان${known?' · قالب مدرسه شناسایی شد':''}</div><div class="form-grid" style="margin-top:15px">${i.workbook?`<label>کاربرگ<select id="sheetChoice">${i.workbook.SheetNames.map(s=>`<option ${s===i.sheetName?'selected':''}>${esc(s)}</option>`).join('')}</select></label>`:''}<label>سطر عنوان ستون‌ها<input id="headerChoice" type="number" min="1" max="${i.rawRows.length}" value="${i.headerRow}"></label><label>نوع تاریخ تولد<select id="calendarChoice"><option value="jalali">شمسی؛ ۱۳۸۹/۰۷/۱۲</option><option value="gregorian">میلادی؛ ۲۰۱۰/۱۰/۰۴</option><option value="excel">عدد سریال اکسل (سیستم ۱۹۰۰)</option></select></label></div>${known?'<p class="dialog-note" style="margin-top:15px">ستون‌های قالب اصلی مدرسه، از جمله نام ترکیبی والدین، درس‌های چندانتخابی و شمارهٔ ضروری، خودکار خوانده می‌شوند. کلاس سال قبل به‌عنوان کلاس فعلی ثبت نمی‌شود.</p>':`<p class="dialog-note" style="margin-top:15px">ستون متناظر هر مشخصه را انتخاب کنید. ستون‌های دیگر هم در پرونده نگهداری می‌شوند. نام کامل یا ترکیب نام و نام خانوادگی لازم است.</p><div class="mapping-grid">${fields.map(f=>`<label>${esc(f.label)}<select data-map="${esc(f.key)}"><option value="-1">— انتخاب نشده —</option>${headers.map((h,n)=>`<option value="${n}" ${mapping[f.key]===n?'selected':''}>${esc(String(h||'ستون '+(n+1)).slice(0,75))}</option>`).join('')}</select></label>`).join('')}</div>`}<div class="import-preview"><table><thead><tr>${headers.slice(0,8).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${i.rows.slice(1,4).map(row=>`<tr>${headers.slice(0,8).map((_,n)=>`<td>${esc(row[n])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button class="button primary" id="reviewImport">بررسی و پیش‌نمایش ورود <i data-lucide="arrow-left"></i></button></div>`;if($('#sheetChoice'))$('#sheetChoice').onchange=e=>{i.sheetName=e.target.value;i.rawRows=XLSX.utils.sheet_to_json(i.workbook.Sheets[i.sheetName],{header:1,defval:'',raw:false,blankrows:true});i.headerRow=1;showImportMapping()};$('#headerChoice').onchange=e=>{i.headerRow=Math.max(1,Number(e.target.value));showImportMapping()};$('#reviewImport').onclick=()=>{try{const res=i.known||rowsToRecords(i.rows,Object.fromEntries($$('[data-map]').map(s=>[s.dataset.map,Number(s.value)])),i.type,$('#calendarChoice').value);previewImport(res)}catch(err){toast(err.message)}};icons()}
function previewImport(res){const i=importState;const current=state.demo?[]:state.records,existing=current.filter(r=>r.type===i.type),oldById=new Map(existing.map(r=>[r.id,r]));const duplicates=res.records.filter(r=>oldById.has(r.id)).length;dialog('بررسی اطلاعات پیش از ورود',`<div class="import-summary"><div><b>${fa(res.records.length)}</b>پروندهٔ قابل ورود</div><div><b>${fa(duplicates)}</b>شناسهٔ موجود</div><div><b>${fa(res.errors.length)}</b>ردیف ردشده</div></div><p class="dialog-note">${esc(i.fileName)} · ${i.type==='student'?'دانش‌آموزان':'دبیران'}${state.demo?' · داده‌های نمونه با ورود این فایل کنار گذاشته می‌شوند.':''}</p><label class="form-label">روش ورود<select class="form-input" id="importMode"><option value="merge">افزودن و به‌روزرسانی شناسه‌های یکسان؛ حفظ عکس‌ها</option><option value="replace">جایگزینی کامل فهرست ${i.type==='student'?'دانش‌آموزان':'دبیران'}</option></select></label>${res.errors.length?`<div class="error-box"><b>ردیف‌های واردنشده</b><br>${res.errors.map(esc).join('<br>')}</div>`:''}${res.warnings.length?`<div class="error-box"><b>موارد نیازمند بررسی</b><br>${res.warnings.map(esc).join('<br>')}</div>`:''}<p class="limit-note">تاریخ‌های نامعتبر وارد پرونده می‌شوند اما تا اصلاح، در تقویم تولد نمایش داده نمی‌شوند. نتیجهٔ بررسی را می‌توانید دریافت کنید.</p><div class="dialog-actions"><button class="button" id="downloadReport">دریافت گزارش</button><button class="button" id="backImport">انتخاب دوبارهٔ فایل</button><button class="button primary" id="confirmImport" ${!res.records.length?'disabled':''}>ورود ${fa(res.records.length)} پرونده</button></div>`);$('#downloadReport').onclick=()=>download(new Blob([JSON.stringify({file:i.fileName,imported:res.records.length,errors:res.errors,warnings:res.warnings},null,2)],{type:'application/json'}),'گزارش-ورود.json');$('#backImport').onclick=importDialog;$('#confirmImport').onclick=async()=>{const mode=$('#importMode').value;let records;if(mode==='replace')records=[...current.filter(r=>r.type!==i.type),...res.records.map(r=>({...r,photo:oldById.get(r.id)?.photo||r.photo}))];else{const all=new Map(current.map(r=>[r.id,r]));res.records.forEach(r=>{const old=all.get(r.id);all.set(r.id,{...old,...r,photo:old?.photo||r.photo})});records=[...all.values()]}state.records=records;state.demo=false;selected=res.records[0]?.id||records[0]?.id;try{await persist();closeDialog();renderAll();toast(fa(res.records.length)+' پرونده وارد شد.')}catch{}}}
function help(){dialog('راهنمای هم‌نشان',`<p class="dialog-note">هم‌نشان برای پیدا کردن سریع آدم‌های مدرسه و آماده‌کردن پیام تولد طراحی شده است.</p><ol class="help-list"><li>چهار رقم آخر موبایل یا تلفن ثابت را در جست‌وجو بنویسید. همهٔ افراد مرتبط و نسبت صاحب شماره نمایش داده می‌شوند. تلفن منزل یا شمارهٔ مشترک هویت قطعی تماس‌گیرنده را مشخص نمی‌کند.</li><li>با نام، کد ملی، شغل والدین، تخصص دبیر یا هر متن موجود در فایل هم جست‌وجو کنید. از «فیلتر» برای محدود کردن شغل و کلاس استفاده کنید.</li><li>روی نام فرد بزنید تا مشخصات کامل را در همین صفحه ببینید. از «ویرایش و عکس» برای اصلاح اطلاعات و افزودن عکس استفاده کنید.</li><li>از تولدهای امروز، هفته یا ماه آینده، کارت تبریک بسازید؛ پیام را ویرایش کنید و تصویر PNG و متن پیام را برای کانال دریافت کنید.</li><li>اطلاعات در دستگاه شما نگهداری می‌شود. از «تنظیمات و پشتیبان» نسخهٔ پشتیبان بگیرید؛ تولدها هنگام باز بودن برنامه هر روز تازه می‌شوند.</li></ol>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action){({import:importDialog,settings:settingsDialog,help,reset:()=>{query='';job='';className='';$('#searchInput').value='';$('#jobFilter').value='';$('#classFilter').value='';renderResults()}}[b.dataset.action])?.()}if(b.dataset.nav)changeNav(b.dataset.nav);if(b.dataset.stat)changeNav(b.dataset.stat);if(b.dataset.type){type=b.dataset.type;page=0;renderResults()}if(b.dataset.person)selectPerson(b.dataset.person);if(b.dataset.query){query=b.dataset.query;$('#searchInput').value=query;page=0;renderResults()}if(b.dataset.copy)copy(b.dataset.copy);if(b.dataset.card)cardDialog(b.dataset.card);if(b.dataset.edit)editDialog(b.dataset.edit);if(b.dataset.days!=null){bdayDays=Number(b.dataset.days);renderBirthdays()}});
$('#searchInput').addEventListener('input',e=>{query=e.target.value;page=0;renderResults()});$('#clearSearch').onclick=()=>{query='';$('#searchInput').value='';page=0;renderResults();$('#searchInput').focus()};$('#filterToggle').onclick=()=>$('#filters').hidden=!$('#filters').hidden;$('#jobFilter').oninput=e=>{job=e.target.value;page=0;renderResults()};$('#classFilter').onchange=e=>{className=e.target.value;page=0;renderResults()};$('#resetFilters').onclick=()=>{job='';className='';$('#jobFilter').value='';$('#classFilter').value='';page=0;renderResults()};$('#prevPage').onclick=()=>{page--;renderResults()};$('#nextPage').onclick=()=>{page++;renderResults()};$('#closeDialog').onclick=closeDialog;$('#mainDialog').addEventListener('click',e=>{if(e.target===$('#mainDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#mainDialog').open)closeDialog();$('#searchInput').focus();$('#searchInput').select()}});
try{db=await openDB();state=await readState();if(!state){const initial=await window.hamneshanDesktop?.loadInitialData?.();state=initial?validateBackup(initial):createDemo();await persist()}}catch(err){state=state||createDemo();toast('ذخیره‌سازی در دسترس نیست. پشتیبان بگیرید.')}selected=state.records[0]?.id;renderAll();let lastDate=todayParts().dateKey;setInterval(()=>{const date=todayParts().dateKey;if(date!==lastDate){lastDate=date;updateHeader();renderStats();renderBirthdays();icons()}},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateHeader();renderStats();renderBirthdays();icons()}});
window.__hamneshanReady=true;
